    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<vector<int>> adj(N + 1);

    for (int i = 1; i <= N; ++i) {
        int M;
        cin >> M;
        for (int j = 0; j < M; ++j) {
            int x;
            cin >> x;
            if (x == i) continue;
            adj[i].push_back(x);
            adj[x].push_back(i);
        }
    }

    vector<int> color(N + 1, -1);
    queue<int> q;

    color[1] = 0;
    q.push(1);

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        for (int v : adj[u]) {
            if (color[v] == -1) {
                color[v] = color[u] ^ 1;
                q.push(v);
            }
        }
    }

    for (int i = 2; i <= N; ++i) {
        if (color[i] == -1) {
            color[i] = 0;
            queue<int> qq;
            qq.push(i);

            while (!qq.empty()) {
                int u = qq.front();
                qq.pop();

                for (int v : adj[u]) {
                    if (color[v] == -1) {
                        color[v] = color[u] ^ 1;
                        qq.push(v);
                    }
                }
            }
        }
    }

    vector<int> team1, team2;

    for (int i = 1; i <= N; ++i) {
        if (color[i] == 0) team1.push_back(i);
        else team2.push_back(i);
    }

    for (int i = 0; i < (int)team1.size(); ++i) {
